// Cloudflare Worker entry (wrangler.jsonc "main"). Serves the OpenNext build
// and adds the scheduled handler that Cron Triggers call.
// https://opennext.js.org/cloudflare/howtos/custom-worker

// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'

type Env = { CRON_SECRET?: string } & Record<string, unknown>
type Ctx = { waitUntil(promise: Promise<unknown>): void }

// Cron schedule (wrangler.jsonc "triggers") → app route it runs.
const CRON_ROUTES: Record<string, string> = {
  '0 13 * * *': '/api/cron/case-digest',
}

export default {
  fetch: handler.fetch,

  // Runs the cron's route through the app itself with CRON_SECRET as a bearer
  // token, so the route still refuses requests from anyone without it. Throwing marks the run as
  // failed in the Cron Events log.
  async scheduled(controller: { cron: string }, env: Env, ctx: Ctx) {
    const path = CRON_ROUTES[controller.cron]
    if (!path) throw new Error(`No route for cron "${controller.cron}"`)
    const request = new Request(`https://cron.internal${path}`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
    })
    const response: Response = await handler.fetch(request, env, ctx)
    const body = await response.text()
    console.log(`[cron] ${path} → ${response.status} ${body}`)
    if (!response.ok) throw new Error(`${path} returned ${response.status}`)
  },
}
